INSERT INTO triage.risk_scores(filing_id,run_id,p_survive,risk_tier,rationale,cost_usd,latency_ms) VALUES ('g00-doc50','2026-10-11-p1-risk-baseline',0.94,'high','Specific tip-pool percentages, an identified manager receiving tips, and an alleged $8.80 hourly wage plausibly support tip-retention and Colorado minimum-wage claims. Missing employment dates, thin individual-employer allegations, and generalized break allegations create partial-dismissal risks, but likely not complete dismissal. Second Circuit overtime pleading rules do not control this Colorado action.',0.0116140,7297) ON CONFLICT (filing_id,run_id) DO UPDATE SET p_survive=EXCLUDED.p_survive,risk_tier=EXCLUDED.risk_tier,rationale=EXCLUDED.rationale,cost_usd=EXCLUDED.cost_usd,latency_ms=EXCLUDED.latency_ms;
