INSERT INTO triage.risk_scores(filing_id,run_id,p_survive,risk_tier,rationale,cost_usd,latency_ms) VALUES ('g01-doc1','2026-10-11-p1-risk-baseline',0.91,'high','The FLSA tip-retention claim plausibly alleges a specific mandatory pool distributing budtenders’ tips to managers and supervisors, with employment dates, pay rate, duties, and distribution mechanics. Paying above minimum wage does not defeat this prohibition. Managerial-status and commerce allegations have some gaps, and unjust enrichment is vulnerable, but complete dismissal is unlikely.',0.0166260,7454) ON CONFLICT (filing_id,run_id) DO UPDATE SET p_survive=EXCLUDED.p_survive,risk_tier=EXCLUDED.risk_tier,rationale=EXCLUDED.rationale,cost_usd=EXCLUDED.cost_usd,latency_ms=EXCLUDED.latency_ms;
