INSERT INTO triage.risk_scores(filing_id,run_id,p_survive,risk_tier,rationale,cost_usd,latency_ms) VALUES ('g02-doc1','2026-10-11-p1-risk-baseline',0.85,'high','The complaint plausibly links unpaid overtime and Wisconsin wages to employer-controlled, non-neutral timeclock rounding. Seventh Circuit pleading standards favor survival without exact weekly calculations. Missing examples, unspecified rounding increments, and contradictory employment dates create vulnerabilities, but likely do not defeat every claim. Class certification and rounding neutrality ordinarily require factual development.',0.0233760,7310) ON CONFLICT (filing_id,run_id) DO UPDATE SET p_survive=EXCLUDED.p_survive,risk_tier=EXCLUDED.risk_tier,rationale=EXCLUDED.rationale,cost_usd=EXCLUDED.cost_usd,latency_ms=EXCLUDED.latency_ms;
