INSERT INTO triage.risk_scores(filing_id,run_id,p_survive,risk_tier,rationale,cost_usd,latency_ms) VALUES ('g03-doc1','2026-10-11-p1-risk-baseline',0.88,'high','The complaint plausibly links recurring overtime to unpaid, interrupted meal periods and excluded shift differentials, with employment dates, duties, shift lengths, and employer control alleged. Missing example workweeks and conclusory willfulness create vulnerabilities, especially because employment ended over two years before filing. Nevertheless, the New Mexico overtime claim provides an independent survival path; certification disputes need not defeat individual claims.',0.0203520,8203) ON CONFLICT (filing_id,run_id) DO UPDATE SET p_survive=EXCLUDED.p_survive,risk_tier=EXCLUDED.risk_tier,rationale=EXCLUDED.rationale,cost_usd=EXCLUDED.cost_usd,latency_ms=EXCLUDED.latency_ms;
