INSERT INTO triage.risk_scores(filing_id,run_id,p_survive,risk_tier,rationale,cost_usd,latency_ms) VALUES ('g04-doc7','2026-10-11-p1-risk-baseline',0.78,'high','The supplied document is an answer/counterclaim, not the complaint, limiting pleading assessment. It nevertheless identifies straight-time overtime payments, a specific hourly rate, employment dates, and separate retaliation allegations. The Motor Carrier Act exemption ordinarily requires factual analysis; collective-action weaknesses would not defeat individual claims. At least one claim likely survives, subject to the missing complaint’s actual allegations.',0.0143060,6946) ON CONFLICT (filing_id,run_id) DO UPDATE SET p_survive=EXCLUDED.p_survive,risk_tier=EXCLUDED.risk_tier,rationale=EXCLUDED.rationale,cost_usd=EXCLUDED.cost_usd,latency_ms=EXCLUDED.latency_ms;
