INSERT INTO triage.risk_scores(filing_id,run_id,p_survive,risk_tier,rationale,cost_usd,latency_ms) VALUES ('g06-doc1','2026-10-11-p1-risk-baseline',0.8,'high','A recurring 50-plus-hour schedule, unpaid overtime policy, and detailed routine duties plausibly support an FLSA claim under First Circuit pleading standards. Exemption likely requires factual development. The principal vulnerability is limitations: employment ended outside the two-year window, making survival depend on adequately pleaded willfulness. Alleged knowledge and selective overtime payments support, but do not establish, willfulness.',0.0096320,7568) ON CONFLICT (filing_id,run_id) DO UPDATE SET p_survive=EXCLUDED.p_survive,risk_tier=EXCLUDED.risk_tier,rationale=EXCLUDED.rationale,cost_usd=EXCLUDED.cost_usd,latency_ms=EXCLUDED.latency_ms;
