INSERT INTO triage.risk_scores(filing_id,run_id,p_survive,risk_tier,rationale,cost_usd,latency_ms) VALUES ('g11-doc1','2026-10-11-p1-risk-baseline',0.94,'high','Detailed allegations of firm control, absent ownership rights, specific wage deductions, and identifiable comparator pay disparities plausibly support employee status and California wage claims. Equal-pay allegations also cover her undisputed employee period. Fraud, tax, and derivative theories face vulnerabilities, but dismissal of every claim appears unlikely; class-certification issues do not eliminate individual claims.',0.0265300,7568) ON CONFLICT (filing_id,run_id) DO UPDATE SET p_survive=EXCLUDED.p_survive,risk_tier=EXCLUDED.risk_tier,rationale=EXCLUDED.rationale,cost_usd=EXCLUDED.cost_usd,latency_ms=EXCLUDED.latency_ms;
