INSERT INTO triage.risk_scores(filing_id,run_id,p_survive,risk_tier,rationale,cost_usd,latency_ms) VALUES ('g12-doc1','2026-10-11-p1-risk-baseline',0.94,'high','The recurring 10 a.m.–8 p.m. weekday schedule and alleged nonpayment plausibly satisfy Second Circuit overtime pleading requirements despite missing pay rates. Dated wage arrears and quantified loans and expenses independently support wage and contract claims. Exempt status is not established by the managing-director title alone. Weak spread-of-hours and collective allegations may narrow, but likely will not eliminate, the case.',0.0166740,6558) ON CONFLICT (filing_id,run_id) DO UPDATE SET p_survive=EXCLUDED.p_survive,risk_tier=EXCLUDED.risk_tier,rationale=EXCLUDED.rationale,cost_usd=EXCLUDED.cost_usd,latency_ms=EXCLUDED.latency_ms;
