INSERT INTO triage.risk_scores(filing_id,run_id,p_survive,risk_tier,rationale,cost_usd,latency_ms) VALUES ('g13-doc62','2026-10-11-p1-risk-baseline',0.95,'high','Alleged five-day, ten-hour schedules, an identified overtime week, quantified unpaid pre/post-shift work, and employer instructions plausibly satisfy Second Circuit overtime pleading standards. FLSA and NYLL claims likely survive even if meal-break, rounding, or class allegations are narrowed. Missing pay rates and template errors are unlikely to defeat all claims.',0.0230760,6673) ON CONFLICT (filing_id,run_id) DO UPDATE SET p_survive=EXCLUDED.p_survive,risk_tier=EXCLUDED.risk_tier,rationale=EXCLUDED.rationale,cost_usd=EXCLUDED.cost_usd,latency_ms=EXCLUDED.latency_ms;
