INSERT INTO triage.risk_scores(filing_id,run_id,p_survive,risk_tier,rationale,cost_usd,latency_ms) VALUES ('g14-doc1','2026-10-11-p1-risk-baseline',0.94,'high','Detailed control allegations plausibly establish employee status, while identified underpayment weeks and substantial expenses support FLSA minimum-wage claims. Unauthorized deductions independently support IWPCA relief. Truth-in-Leasing allegations identify specific charges and escrow defects, although statutory miscitation and lease applicability create vulnerabilities. Missing exact weekly wage calculations could narrow claims but are unlikely to produce complete dismissal.',0.0175180,8260) ON CONFLICT (filing_id,run_id) DO UPDATE SET p_survive=EXCLUDED.p_survive,risk_tier=EXCLUDED.risk_tier,rationale=EXCLUDED.rationale,cost_usd=EXCLUDED.cost_usd,latency_ms=EXCLUDED.latency_ms;
