INSERT INTO triage.risk_scores(filing_id,run_id,p_survive,risk_tier,rationale,cost_usd,latency_ms) VALUES ('x2-doc25','2026-10-11-p1-risk-baseline',0.94,'high','Specific workweeks, hours, rates, and earnings plausibly establish at least one FLSA overtime claim, particularly the February 2022 allegation of 40.7 hours paid entirely at straight time. These facts exceed conclusory pleading under Sixth Circuit standards. Regular-rate arithmetic and state-law theories invite challenges, but class-certification issues should not defeat all individual claims.',0.0288220,9262) ON CONFLICT (filing_id,run_id) DO UPDATE SET p_survive=EXCLUDED.p_survive,risk_tier=EXCLUDED.risk_tier,rationale=EXCLUDED.rationale,cost_usd=EXCLUDED.cost_usd,latency_ms=EXCLUDED.latency_ms;
