INSERT INTO triage.risk_scores(filing_id,run_id,p_survive,risk_tier,rationale,cost_usd,latency_ms) VALUES ('x3-doc1','2026-10-11-p1-risk-baseline',0.98,'high','Specific pay rates, schedules, dated time-record alterations, unpaid training, and manager tip diversion plausibly support multiple wage claims. Missing tip-credit notice strongly supports NYLL minimum-wage liability. Shared scheduling, staffing, supplies, and direct supervision substantiate employer allegations. Wage-notice standing and payment-frequency remedies may be contested, but full dismissal is unlikely.',0.0312040,8215) ON CONFLICT (filing_id,run_id) DO UPDATE SET p_survive=EXCLUDED.p_survive,risk_tier=EXCLUDED.risk_tier,rationale=EXCLUDED.rationale,cost_usd=EXCLUDED.cost_usd,latency_ms=EXCLUDED.latency_ms;
