INSERT INTO triage.risk_scores(filing_id,run_id,p_survive,risk_tier,rationale,cost_usd,latency_ms) VALUES ('x4-doc1','2026-10-11-p1-risk-baseline',0.97,'high','Specific unpaid tasks, daily time estimates, employer directives, and a dated paystub showing paid overtime plausibly establish uncompensated overtime under First Circuit pleading standards. Detailed bonus allegations provide another FLSA theory. Contract, unjust-enrichment, and nationwide-class issues may narrow the action but are unlikely to defeat every claim. No arbitration barrier appears in the complaint.',0.0285120,8074) ON CONFLICT (filing_id,run_id) DO UPDATE SET p_survive=EXCLUDED.p_survive,risk_tier=EXCLUDED.risk_tier,rationale=EXCLUDED.rationale,cost_usd=EXCLUDED.cost_usd,latency_ms=EXCLUDED.latency_ms;
