INSERT INTO triage.risk_scores(filing_id,run_id,p_survive,risk_tier,rationale,cost_usd,latency_ms) VALUES ('e00-doc1','2026-10-11-p1-risk-baseline',0.95,'high','Employment dates, cash wages, tip-pool allocations, and noncustomer-facing recipients plausibly establish minimum-wage violations through invalid tip credits. Federal and DC notice theories provide additional routes to survival. Joint-employer allegations and side-work theories face vulnerabilities, but those likely produce only partial dismissal. Overtime-specific pleading requirements are inapplicable, and no arbitration agreement appears.',0.0307400,5552) ON CONFLICT (filing_id,run_id) DO UPDATE SET p_survive=EXCLUDED.p_survive,risk_tier=EXCLUDED.risk_tier,rationale=EXCLUDED.rationale,cost_usd=EXCLUDED.cost_usd,latency_ms=EXCLUDED.latency_ms;
