INSERT INTO triage.risk_scores(filing_id,run_id,p_survive,risk_tier,rationale,cost_usd,latency_ms) VALUES ('e03-doc1','2026-10-11-p1-risk-baseline',0.5,'medium','The supplied document is a notice of removal, not the complaint; referenced Exhibit B is unavailable. It identifies FLSA and two D.C. wage claims with collective/class allegations, but supplies no underlying employment or pay facts. Pleading sufficiency, exemptions, and arbitration defenses therefore cannot be assessed reliably.',0.0052320,5157) ON CONFLICT (filing_id,run_id) DO UPDATE SET p_survive=EXCLUDED.p_survive,risk_tier=EXCLUDED.risk_tier,rationale=EXCLUDED.rationale,cost_usd=EXCLUDED.cost_usd,latency_ms=EXCLUDED.latency_ms;
