INSERT INTO triage.risk_scores(filing_id,run_id,p_survive,risk_tier,rationale,cost_usd,latency_ms) VALUES ('e07-doc1','2026-10-11-p1-risk-baseline',0.94,'high','Specific allegations of uncompensated loading and workday travel plausibly support D.C. wage claims independently of disputed Davis-Bacon entitlement. Employment dates, pay rates, and individual defendants’ control are detailed. Overtime allegations lack quantified weeks, and prevailing-wage theories face legal hurdles, but dismissal of every claim is unlikely. Contractor liability supplies an additional route against Mid-Atlantic.',0.0176800,6815) ON CONFLICT (filing_id,run_id) DO UPDATE SET p_survive=EXCLUDED.p_survive,risk_tier=EXCLUDED.risk_tier,rationale=EXCLUDED.rationale,cost_usd=EXCLUDED.cost_usd,latency_ms=EXCLUDED.latency_ms;
