INSERT INTO triage.risk_scores(filing_id,run_id,p_survive,risk_tier,rationale,cost_usd,latency_ms) VALUES ('e10-doc1','2026-10-11-p1-risk-baseline',0.96,'high','Concrete allegations of 60–70-hour weeks, salary amounts, unpaid overtime, and nonexempt duties plausibly support wage claims. Named comparators, disparate work assignments, and discrimination complaints followed by termination support Section 1981 claims. DCHRA limitations and thin FLSA coverage allegations create vulnerabilities, but dismissal of every claim is unlikely.',0.0163500,7241) ON CONFLICT (filing_id,run_id) DO UPDATE SET p_survive=EXCLUDED.p_survive,risk_tier=EXCLUDED.risk_tier,rationale=EXCLUDED.rationale,cost_usd=EXCLUDED.cost_usd,latency_ms=EXCLUDED.latency_ms;
