INSERT INTO triage.risk_scores(filing_id,run_id,p_survive,risk_tier,rationale,cost_usd,latency_ms) VALUES ('g05-doc1','2026-10-11-p1-risk-baseline',0.9,'high','The complaint plausibly alleges recurring overtime and a concrete policy withholding pay for hours 40–45, alongside hourly compensation inconsistent with the asserted exemption. Under Sixth Circuit pleading standards, missing example workweeks or pay rates likely is not fatal. Salary-basis and public-employer exceptions require factual development; collective-certification issues should not defeat the individual claim.',0.0091400,6419) ON CONFLICT (filing_id,run_id) DO UPDATE SET p_survive=EXCLUDED.p_survive,risk_tier=EXCLUDED.risk_tier,rationale=EXCLUDED.rationale,cost_usd=EXCLUDED.cost_usd,latency_ms=EXCLUDED.latency_ms;
